using System;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 public sealed class MetaSaveTests {
  static string Hash(string text){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-","").ToLowerInvariant();}
  [Test]public void VersionThreePreservesIntItemsWorkAndOriginalBeforeVersionFourCommit(){string dir=Path.Combine(Path.GetTempPath(),"unity-meta-migration-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var codec=new UnitySaveCodec();var s=Game.New(1000);s=Game.Buy(s,"calculator");s=Workshop.Discover(s);s=Workshop.Craft(s,"impulse-relay");s=Workshop.Equip(s,s.Workshop.inventory[0].id);s.Prestige.lab=s.Prestige.labSeed=true;s.Prestige.knowledge=ScientificNumber.From(321).ToData();s.Prestige.Entitlement=ScientificNumber.From(10);s=PrestigeRules.Reset(s);s.Credits=ScientificNumber.From(100000);s.Data=ScientificNumber.From(10000);s=Game.Buy(s,"sbc");s.Research[Game.ResearchIndex("blueprints")]=1;s=Game.Train(s,"quality");s=Game.Research(s,"dataGeneration");s=MaterialAnalysis.Start(s,0);s=Workshop.StartModule(s,0);s=Game.Advance(s,s.SavedAt+1000);Assert.That(s.Training,Is.Not.Null);Assert.That(s.ResearchJob,Is.Not.Null);Assert.That(s.Workshop.hasAnalysis&&s.Workshop.hasModuleJob,Is.True);var dto=StateData.From(s);dto.meta=null;string payload=codec.Encode(dto),raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=3,payload=payload,sha256=Hash(payload)}),path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,codec);var loaded=store.Load(s.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);var expected=StateData.From(s);expected.meta=loaded.State.Meta.Copy();Assert.That(JsonUtility.ToJson(StateData.From(loaded.State)),Is.EqualTo(JsonUtility.ToJson(expected)));Assert.That(loaded.State.Prestige.knowledge.m,Is.EqualTo(s.Prestige.knowledge.m));Assert.That(loaded.State.Meta.models.All(l=>l== -1),Is.True,"No free model");Assert.That(loaded.State.Meta.tutorial,Is.EqualTo("lab"));Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v3-original-*").Single()),Is.EqualTo(raw));store.Save(loaded.State);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(4));Assert.That(File.ReadAllText(path+".backup"),Is.EqualTo(raw));}finally{Directory.Delete(dir,true);}}
  [Test]public void InvalidFutureOrMissingMetaCannotOverwriteOriginal(){var dto=StateData.From(Game.New(1000));dto.meta=null;Assert.Throws<FormatException>(()=>dto.ToState());var s=Game.New(1000);s.Meta.models[0]=99;Assert.Throws<FormatException>(()=>Game.Validate(s));s=Game.New(1000);s.Meta.axiomMinimum=ScientificNumber.Zero.ToData();Assert.Throws<FormatException>(()=>Game.Validate(s));s=Game.New(1000);s.Meta.available=ScientificNumber.One.ToData();Assert.Throws<FormatException>(()=>Game.Validate(s));}
 }
}
